*******************************************************************************
* v3sprite.asm -- video3's 16x16 sprite on the host emulator.  GENERATED by
* bench/mkv3sprite.py; edit the generator.
*
*   sh hardware/video3/bench/run-v3sprite.sh
*
* plan 7.  The shape is the top 64 bytes of MAPBASE's 64 KB of VRAM.
* The sprite's two bits per pixel are the LUT's ATTR in bitmap mode:
* 0 is transparent, 1 and 2 select sub-palettes 1 and 2.  The ROM steps through
* every X phase and writes the position to $C208/$C20A, which machine.c records
* with every frame - so one run covers all of them.
*******************************************************************************

VCTRL   EQU     $FF60
VSCROLL EQU     $FF61
WPTR0   EQU     $FF68
WPTR1   EQU     $FF69
WPTR2   EQU     $FF6A
WADV    EQU     $FF6B
VDATA   EQU     $FF6C
VSTAT   EQU     $FF6D
VCTRL2  EQU     $FF60
PIDXL   EQU     $FF6E
PIDXH   EQU     $FF6F
PDATL   EQU     $FF70
PDATH   EQU     $FF71
SPRX    EQU     $FF7A
SPRY    EQU     $FF7B
SPRH    EQU     $FF7C
MAPBAS  EQU     $FF79
SIMPORT EQU     $FF2F

MKX     EQU     $C208           machine.c records these with every frame
MKY     EQU     $C20A
row     EQU     $C100
seed    EQU     $C102

        ORG     $8000
        FCC     "6309"
        JMP     start

        SETDP   $FF
start   orcc    #$50
        lds     #$E000
        lda     #$FF
        tfr     a,dp
        clr     <VCTRL
        clr     <WADV
        clr     <VSCROLL
        clr     <VSCROLL+1
        clr     <SPRH           the sprite is off while the screen is built
        ldd     #$FFFF          ... and the frames recorded meanwhile carry a
        std     MKX             position no test uses, so the checker skips them
        std     MKY

* --- sub-palette 0: entry i = i * $0101.  Sub-palettes 1 and 2 are the two
*     cursor colours, ALL 256 entries each (plan 7): $F800 and $001F.
        clr     <PIDXH
        clr     <PIDXL
        clrb
p0      stb     <PDATL
        stb     <PDATH
        incb
        bne     p0
        lda     #1
        sta     <PIDXH
        clr     <PIDXL
        clrb
p1      clr     <PDATL
        lda     #$F8
        sta     <PDATH
        incb
        bne     p1
        lda     #2
        sta     <PIDXH
        clr     <PIDXL
        clrb
p2      lda     #$1F
        sta     <PDATL
        clr     <PDATH
        incb
        bne     p2

* --- the background: VRAM[r][c] = (r * 7 + c * 3) & $FF, as v3copy uses
        clr     row
        clr     row+1
fr1     ldd     row
        lslb
        rola
        lslb
        rola
        clr     <WPTR0
        stb     <WPTR1
        sta     <WPTR2
        ldb     row+1
        lda     #7
        mul
        stb     seed
        ldy     #640
fc1     lda     seed
        sta     <VDATA
        adda    #3
        sta     seed
        leay    -1,y
        bne     fc1
        ldd     row
        addd    #1
        std     row
        cmpd    #200
        blo     fr1

* --- the shape: 64 bytes of VRAM at MAPBASE's top (plan 7), written with
*     ordinary VDATA writes - and its complement at MAPBASE 0's top, the decoy
        lda     #$00
        sta     <WPTR2
        lda     #$FF
        sta     <WPTR1
        lda     #$C0
        sta     <WPTR0
        ldx     #shape
        ldb     #64
sh0     lda     ,x+
        coma
        sta     <VDATA
        decb
        bne     sh0
        lda     #$07
        sta     <WPTR2
        lda     #$FF
        sta     <WPTR1
        lda     #$C0
        sta     <WPTR0
        ldx     #shape
        ldb     #64
sh1     lda     ,x+
        sta     <VDATA
        decb
        bne     sh1
        lda     #7
        sta     <MAPBAS         selects the shape in bitmap mode

        lda     #$A0
        sta     SIMPORT

